#!/bin/zsh
cd "$(dirname "$0")"
D="$(pwd)/gen"
S="ESTILO: pixel art de videojuego estilo Pokémon Esmeralda / Pokémon Rojo Fuego (Game Boy Advance), vista desde arriba en 3/4, colores brillantes, alegres y tiernos, contornos oscuros limpios, píxeles nítidos, para una niña. SIN texto, SIN letras, SIN números, SIN marcas de agua."
KEY="El FONDO debe ser magenta puro liso (#FF00FF) en toda la imagen, sin degradado, sin sombras en el fondo; cada sprite bien separado de los demás con espacio magenta alrededor. No uses color magenta dentro de los dibujos."
WALK="hoja de sprites para caminar: EXACTAMENTE 4 filas y 3 columnas (12 cuadros del mismo tamaño, alineados en cuadrícula). Fila 1: caminando hacia ABAJO (de frente), fila 2: caminando hacia la IZQUIERDA, fila 3: caminando hacia la DERECHA, fila 4: caminando hacia ARRIBA (de espaldas). En cada fila: columna 1 paso con pie izquierdo, columna 2 parado, columna 3 paso con pie derecho. Personaje chibi cabezón como los entrenadores de Pokémon."
run(){ name=$1; shift; (codex exec --dangerously-bypass-approvals-and-sandbox --skip-git-repo-check "Usa tu herramienta de generación de imágenes. $* Al final imprime NOMBRE => RUTA COMPLETA de cada imagen generada (aunque no hayas podido copiarla)." < /dev/null > log1-$name.txt 2>&1; echo "DONE $name $?") & }
run lucy "$S $KEY Crea lucy.png (CUADRADA 1:1) en $D/: $WALK La protagonista LUCY: niña tierna de unos 6 años, cabello castaño largo en dos colitas con moños rosas, gorrito de chef blanco chiquito, vestido rosa con delantal blanco con un corazón, zapatitos rojos."
run npc1 "$S $KEY Crea 2 imágenes CUADRADAS (1:1) en $D/: npc-a.png: $WALK Una señora amable con chongo gris, lentes, suéter morado y falda azul. npc-b.png: $WALK Un niño con gorra azul al revés, playera amarilla y short verde."
run npc2 "$S $KEY Crea 2 imágenes CUADRADAS (1:1) en $D/: npc-c.png: $WALK Una niña con cabello rubio corto y vestido verde menta. npc-d.png: $WALK Un señor abuelito con bigote blanco, boina café, chaleco y bastón."
run staff "$S $KEY Crea 3 imágenes CUADRADAS (1:1) en $D/: baker.png: $WALK Un panadero gordito con gorro de chef alto, bigote y delantal blanco. cashier.png: $WALK Una cajera joven con cabello negro en coleta, playera rosa y delantal de rayas rosa con blanco. helper.png: $WALK Un repartidor joven con gorra roja, chamarra roja y mochila de entregas."
run bld1 "$S $KEY Crea 2 imágenes ANCHAS (16:9) en $D/: buildings-a.png con EXACTAMENTE 3 edificios en una fila, cada uno completo, vistos desde arriba en 3/4 estilo pueblo de Pokémon con su puerta al frente abajo: 1) la PASTELERÍA de Lucy: edificio rosa pastel con toldo de rayas rosa y blanco, ventanales con pasteles exhibidos, y un pastel gigante de fresa como adorno en el techo; 2) un GRANERO rojo de granja con silo y su puerta grande; 3) un MOLINO de harina con aspas y base de piedra. buildings-b.png con EXACTAMENTE 3 edificios en una fila: 1) una FRUTERÍA/mercado con toldo verde y cajas de fresas, manzanas y limones al frente; 2) una CHOCOLATERÍA de color café con toldo crema y un chocolate gigante en el techo; 3) una tienda de abarrotes azul con toldo azul y blanco y bultos de azúcar al frente."
run bld2 "$S $KEY Crea 2 imágenes ANCHAS (16:9) en $D/: houses.png con EXACTAMENTE 4 casitas distintas en una fila (techo rojo, techo azul, techo verde, techo morado), vistas desde arriba en 3/4 estilo Pokémon, con su puerta al frente. props.png con EXACTAMENTE 12 objetos en 3 filas de 4, cada uno del mismo tamaño: árbol redondo grande, pino, arbusto de fresas con fresas rojas, manzano con manzanas, arbusto de flores, fuente redonda con agua, banca de parque, farol, cerca de madera corta, buzón, gallina blanca, vaca."
run interior "$S $KEY Crea 2 imágenes ANCHAS (16:9) en $D/: furniture.png con EXACTAMENTE 8 muebles de una pastelería en 2 filas de 4, vistos desde arriba en 3/4 estilo interior de Pokémon: horno de ladrillo pequeño, horno grande dorado elegante, mesa de trabajo con tazón y batidora, vitrina de vidrio para pasteles (vacía), mostrador con caja registradora, mesita redonda con dos sillas, maceta con planta, estante con harina y frascos. decor.png con EXACTAMENTE 8 objetos decorativos en 2 filas de 4: alfombra redonda rosa, cuadro de un pastel en la pared, reloj de pared, lámpara de techo, globos de colores, ventana con cortinas, pizarrón de menú (sin letras), florero con flores."
run items "$S $KEY Crea 2 imágenes ANCHAS (16:9) en $D/: ingredients.png con EXACTAMENTE 12 íconos en 3 filas de 4, cada uno del mismo tamaño: huevo, botella de leche, barra de mantequilla, costal de harina, bolsa de azúcar, fresa, manzana roja, limón, barra de chocolate, frasco de vainilla, chispas de colores, crema batida en tazón. desserts.png con EXACTAMENTE 12 postres en 3 filas de 4, cada uno del mismo tamaño: galleta con chispas, cupcake rosa con fresa, dona glaseada rosa con chispas, pay de manzana, pastel de fresa con crema, brownie, macarons de colores, croissant, pastel de chocolate de tres pisos, pay de limón con merengue, cuernito relleno de crema, pastel de cumpleaños con velita."
run title "ESTILO: ilustración de videojuego pixel art HD tierna estilo Pokémon de GBA pero en alta resolución, colores pastel brillantes, SIN texto, SIN letras. Crea 3 imágenes en $D/: title-wide.png (16:9) y title-tall.png (9:16): portada de un juego: un pueblito encantador visto desde arriba con calles, árboles, una granja, un molino y al centro una pastelería rosa; la niña Lucy (cabello castaño en dos colitas con moños rosas, gorrito de chef, vestido rosa con delantal) saludando feliz con una bandeja de cupcakes; la parte de ARRIBA despejada (cielo) para poner un título. icon-bakery.png CUADRADO (1:1) lleno con fondo rosa degradado: Lucy sonriendo junto a un pastel de fresa gigante y su pastelería al fondo."
wait
echo ALLDONE
